// Author: MiYu. Cross-native research commands, custom upgrade inheritance and production reentry consumers.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_research_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto forge=vm.global("probe_forge").bits,second=vm.global("probe_second").bits,footman=vm.global("probe_footman").bits,type=ObjectData::code("R0T1");auto& states=session.config().players[0].states;float baseHP=std::bit_cast<float>(session.units().at(footman)->maxLife.bits());
        auto buttons=session.commands(forge,0);check(std::any_of(buttons.begin(),buttons.end(),[&](auto& button){return button.type==type && button.action==CommandAction::Research && button.gold==10 && button.lumber==7 && button.enabled && button.name=="First";}),"Custom upgrade not consumed by command panel");check(session.research(forge,type) && !session.research(second,type),"Duplicate research reservation was accepted");check(states.at(1)==990 && states.at(2)==993 && vm.global("probe_started").bits==1,"Research payment/start consumer differs");check(session.cancelProduction(forge) && states.at(1)==1000 && states.at(2)==1000 && vm.global("probe_cancelled").bits==1,"Research cancellation/refund consumer differs");
        auto player=vm.handle("player",0x100000);check(vm.invoke("IssueImmediateOrder",std::array{vm.handle("unit",forge),vm.string("R0T1")}).bits!=0,"String research command not consumed");session.advance(2);auto unit=session.units().at(footman);check(vm.global("probe_finished").bits==1 && unit->technology.dice==1 && unit->technology.damage==4 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+20,"Completed upgrade did not reach live unit");auto created=vm.invoke("CreateUnit",std::array{player,vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("hfoo"))),vm.real(unit->x),vm.real(unit->y),vm.real(unit->facing)});check(session.units().at(created.bits)->technology.dice==1,"New unit did not inherit research");check(session.research(forge,type),"Second level prerequisite override not consumed");session.advance(2);check(vm.global("probe_finished").bits==2 && unit->technology.dice==2 && unit->technology.damage==8 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+40,"Second level or repeated effect differed");
        vm.invoke("SetPlayerTechResearched",std::array{player,vm.integer(std::bit_cast<std::int32_t>(type)),vm.integer(0)});check(unit->technology.dice==2 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+40,"SetPlayerTechResearched lowered existing research");vm.invoke("ProbeCancelOnStart");check(session.research(forge,type) && session.units().at(forge)->production.empty(),"Start callback cancellation corrupted queue");check(states.at(1)==975 && states.at(2)==983,"Reentrant cancellation lost refund");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS research consumers: custom levels, commands, payment/refund, duplicate lock, events, current/new units and callback cancellation\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
